MAP
    NAME "SS_MAP_PLAN_TANQUES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_tanques.log"
    DEBUG 0
    LAYER
        NAME "SS_MAP_PLAN_TANQUES"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        CONNECTIONTYPE POSTGIS
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "geometry from tanques using unique gid using srid=32614"
        TYPE POINT
        LABELITEM "name"
        LABELCACHE on
        CLASS
            NAME "Tanques"
            STYLE
                SYMBOL "puntos"
                SIZE 10
                COLOR 182 183 236
                OUTLINECOLOR 0 0 0
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "ARIAL"
                OFFSET 0 12
                SIZE 19
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP